#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "AArenaGameMode::ScoreTracker in Source/PixelArena/ArenaGameMode.h was a raw UArenaScoreTracker* pointer without UPROPERTY(). Because Unreal's Garbage Collector could not trace the reference, ScoreTracker was garbage collected during play (LogGarbage: Collecting garbage: 412 objects purged), leaving a dangling pointer that caused EXCEPTION_ACCESS_VIOLATION when AArenaGameMode::OnGoalScored() called ScoreTracker->AddPoints().",
  "no_colors_cause": "AArenaGameMode::BeginPlay() dynamically loads /Game/Data/Palettes/DA_Primary.DA_Primary via LoadObject() using a runtime string path. In Config/DefaultGame.ini, bCookAll=False and DirectoriesToAlwaysCook only included /Game/Data/Effects, not /Game/Data/Palettes, so the palette asset was not cooked into the packaged build and fell back to gray."
}
